import{_ as n,o as a,c as t,a2 as i}from"./chunks/framework.CtQGab4e.js";const b=JSON.parse('{"title":"Importeren in Label-wise","description":"","frontmatter":{},"headers":[],"relativePath":"plattegrond/label-wise.md","filePath":"plattegrond/label-wise.md"}'),l={name:"plattegrond/label-wise.md"};function o(r,e,s,d,m,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="importeren-in-label-wise" tabindex="-1">Importeren in Label-wise <a class="header-anchor" href="#importeren-in-label-wise" aria-label="Permalink to &quot;Importeren in Label-wise&quot;">​</a></h1><p>Van het 3D-model maak je een importbestand voor Label-wise: de rekenzones met hun constructies, oppervlaktes, oriëntatie en helling, en de kozijnen als deelvlak.</p><h2 id="het-bestand-maken" tabindex="-1">Het bestand maken <a class="header-anchor" href="#het-bestand-maken" aria-label="Permalink to &quot;Het bestand maken&quot;">​</a></h2><ol><li><a href="./kozijnen-koppelen.html">Koppel de kozijnen</a>.</li><li>Tik in het <a href="./3d-paneel.html">3D-paneel</a> op <strong>Exporteren</strong> en laat <strong>Label-wise</strong> aangevinkt. Je krijgt <code>Label-wise import.json</code>, eventueel samen met de andere bestanden in een zip (zie <a href="./export-3d.html#uit-het-3d-paneel">Exporteren voor 3D</a>).</li><li>Kijk in het log van het 3D-paneel: daar staat wat je in Label-wise nog moet nakijken of invullen, per zone.</li></ol><h2 id="importeren" tabindex="-1">Importeren <a class="header-anchor" href="#importeren" aria-label="Permalink to &quot;Importeren&quot;">​</a></h2><p>Tik in Label-wise in het projectenoverzicht op <strong>Importeren</strong> en sleep het bestand naar het venster.* Vul in het importvenster het <strong>bouwjaar</strong> in: zonder bouwjaar kun je niet bevestigen.</p><p class="opmerking">* Importeren in een bestaand project kan nog niet.</p><h2 id="zelf-invullen-in-label-wise" tabindex="-1">Zelf invullen in Label-wise <a class="header-anchor" href="#zelf-invullen-in-label-wise" aria-label="Permalink to &quot;Zelf invullen in Label-wise&quot;">​</a></h2><ul><li>het <strong>beslisschema</strong> van elke dichte constructie (vloer, gevel, dak);</li><li>de <strong>Ag</strong> per rekenzone;</li><li>de <strong>perimeter</strong> van de vloeren;</li><li>bij een kelderwand: de vloer en de diepte onder maaiveld;</li><li>wat het log noemt, bijvoorbeeld een overstek zonder maten of de g-waarden van vaste zonwering.</li></ul><p>Vergeet je een beslisschema, dan meldt Label-wise dat bij het berekenen.</p><h2 id="wat-het-bestand-doet" tabindex="-1">Wat het bestand doet <a class="header-anchor" href="#wat-het-bestand-doet" aria-label="Permalink to &quot;Wat het bestand doet&quot;">​</a></h2><ul><li>Elke <a href="./installaties.html">klimatiseringszone</a> wordt een rekenzone.</li><li>Elke constructie uit het 3D-paneel wordt één vlak, met de m² inclusief je <a href="./constructies.html">correcties</a>. De kozijnen zijn al van de m² afgetrokken.</li><li>De helling wordt afgerond op 15°, want Label-wise kent alleen stappen van 15°. Het log noemt elke afronding.</li><li>Elk vlak krijgt een constructie uit een vaste lijst, op basis van het <a href="./gebouw.html#gebouwdelen">gebouwdeel</a>. Begint de naam van een gebouwdeel met <em>Aanbouw</em>, <em>Opbouw</em> of <em>Dakkapel</em>, dan krijgt het de constructies van een aanbouw, opbouw of dakkapel. Bij elke andere naam (<em>Erker</em>, <em>Garage</em>) die van het hoofdhuis, met een melding in het log.</li></ul><div class="tip custom-block"><p class="custom-block-title">Projectnaam</p><p>De titel van je notitie wordt de naam van het project in Label-wise. Geef de notitie dus het adres als titel.</p></div>',13)])])}const k=n(l,[["render",o]]);export{b as __pageData,k as default};
